import React, { useEffect, useState } from 'react'
import './VenueDetail.css'
import { Link } from 'gatsby'
import { 
  MapPin, 
  Train, 
  Users, 
  Calendar,
  ArrowLeft,
  ExternalLink,
  Star,
  Coffee,
  Camera,
  Navigation,
  Clock,
  Wifi,
  ParkingCircle,
  Package,
  Globe,
  Ticket,
  Plane,
  Bus,
  Info,
  Hash
} from 'lucide-react'
import { getVenueById, VENUES_2026, AccessRoute, NearbyAttraction, HolyPlace, type Venue } from '../../data/venues'
import { VenueAttendeesList } from '../attendance/VenueAttendeesList'
import { AttendanceButton } from '../attendance/AttendanceButton'
import { useAuth } from '../../contexts/AuthContext'
import { supabase } from '../../lib/supabase'
import { FacilityItem } from './FacilityItem'
import { getPrefectureGradient } from '../../data/prefectureColors'
import { DEFAULT_GRADIENT } from '../../data/venues/gradients'
import { VenueTravelChecklist } from './VenueTravelChecklist'

interface VenueDetailProps {
  venueId: string
}

const VenueDetail: React.FC<VenueDetailProps> = ({ venueId }) => {
  const venue = getVenueById(venueId)
  const { user } = useAuth()
  const [mapLoaded, setMapLoaded] = useState(false)
  const [showAllVenues, setShowAllVenues] = useState(false)
  const [isAttending, setIsAttending] = useState(false)
  const [loadingAttendance, setLoadingAttendance] = useState(true)
  const [isNavFixed, setIsNavFixed] = useState(false)

  // ページ内ナビゲーション用のセクション定義（存在するセクションのみ表示）
  const sections = venue ? [
    { id: 'info', label: '基本情報', condition: true },
    { id: 'attendees', label: '参加者', condition: true },
    { id: 'access', label: 'アクセス', condition: !!(venue.access || venue.longDistanceAccess) },
    { id: 'lockers', label: 'ロッカー', condition: true },
    { id: 'parking', label: '駐車場', condition: true },
    { id: 'cafes', label: 'カフェ', condition: !!(venue.cafes && venue.cafes.length > 0) },
    { id: 'restaurants', label: '飲食店', condition: true },
    { id: 'spots', label: '観光', condition: true },
    { id: 'holy', label: '聖地', condition: !!(venue.holyPlaces && venue.holyPlaces.length > 0) },
    { id: 'hotels', label: '宿泊', condition: !!(venue.accommodations && venue.accommodations.length > 0) },
  ].filter(section => section.condition) : []

  // スクロール位置を監視してナビゲーションを固定
  useEffect(() => {
    const handleScroll = () => {
      const infoSection = document.getElementById('info')
      if (infoSection) {
        const infoBottom = infoSection.offsetTop + infoSection.offsetHeight
        setIsNavFixed(window.scrollY > infoBottom)
      }
    }
    window.addEventListener('scroll', handleScroll)
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  // スムーズスクロール関数
  const scrollToSection = (sectionId: string) => {
    const element = document.getElementById(sectionId)
    if (element) {
      const offset = 80 // 固定ナビの高さ分のオフセット
      const elementPosition = element.getBoundingClientRect().top + window.pageYOffset
      window.scrollTo({
        top: elementPosition - offset,
        behavior: 'smooth'
      })
    }
  }

  // 参加状態を確認
  useEffect(() => {
    const checkAttendance = async () => {
      if (!user || !supabase) {
        setLoadingAttendance(false)
        return
      }

      try {
        const { data, error } = await supabase
          .from('venue_attendances')
          .select('*')
          .eq('user_id', user.id)
          .eq('venue_id', venueId)
          .single()

        if (data && !error) {
          setIsAttending(true)
        }
      } catch (error) {
        console.error('参加状態の確認エラー:', error)
      } finally {
        setLoadingAttendance(false)
      }
    }

    checkAttendance()
  }, [user, venueId])

  // 会場が見つからない場合
  if (!venue) {
    return (
      <div className="min-h-screen p-4">
        <div className="max-w-4xl mx-auto">
          <div className="text-center py-20">
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-4">
              会場が見つかりません
            </h1>
            <Link 
              to="/bijigaku-navi/"
              className="text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
            >
              ← トップページに戻る
            </Link>
          </div>
        </div>
      </div>
    )
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    const options: Intl.DateTimeFormatOptions = { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric',
      weekday: 'long'
    }
    return date.toLocaleDateString('ja-JP', options)
  }

  // Google Maps埋め込みURL生成（標準iframe、APIキー不要）
  const getGoogleMapsEmbedUrl = () => {
    // 専用の埋め込みURLがある場合はそれを使用
    if (venue.mapEmbedUrl) return venue.mapEmbedUrl
    // それ以外は従来の方法で生成
    if (!venue.location.address) return null
    const query = encodeURIComponent(`${venue.name} ${venue.location.address}`)
    return `https://maps.google.com/maps?q=${query}&output=embed&z=15`
  }

  // Google Maps検索URL
  const getGoogleMapsSearchUrl = () => {
    if (!venue.location.address) return null
    const query = encodeURIComponent(`${venue.name} ${venue.location.address}`)
    return `https://www.google.com/maps/search/${query}`
  }

  // 会場のグラデーション背景を取得する関数
  const getVenueGradient = (venue: Venue): string => {
    // 1. 会場個別のグラデーション設定があればそれを優先
    if (venue.gradient) {
      return `linear-gradient(135deg, ${venue.gradient.from}, ${venue.gradient.to})`
    }
    // 2. 都道府県カラーを適用
    const prefectureGradient = getPrefectureGradient(venue.location.prefecture)
    if (prefectureGradient !== 'rgba(216, 217, 195, 0.9)') {
      return prefectureGradient
    }
    // 3. デフォルトは単色
    return DEFAULT_GRADIENT.from
  }

  return (
    <>
      {/* 会場基本情報（横幅いっぱい） */}
      <div
        id="info"
        className="relative"
        style={{
          background: getVenueGradient(venue),
          margin: 0,
          padding: 0,
          borderRadius: 0,
          boxShadow: 'none',
        }}
      >
        <div className="w-full px-4 md:px-12 lg:px-32 py-8 md:py-12 lg:py-16">
              <div className="flex items-start gap-4 mb-4">
                <h1 className="text-2xl font-bold text-white">
                  {venue.name}
                </h1>
              </div>
              <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-sm text-white mb-3">
                <div className="flex items-center gap-1">
                  <Calendar className="h-4 w-4 text-white" />
                  <span>{formatDate(venue.date)}</span>
                </div>
                <div className="flex items-center gap-1">
                  <MapPin className="h-4 w-4 text-white" />
                  <span>{venue.location.prefecture}</span>
                </div>
                <div className="flex items-center gap-1">
                  <Users className="h-4 w-4 text-white" />
                  <span>{venue.capacity ? `${venue.capacity}人` : '未定'}</span>
                </div>
              </div>

              {/* Google Maps埋め込み */}
              {getGoogleMapsEmbedUrl() && (
                <div className="mt-4 mb-4">
                  <div className="relative h-64 overflow-hidden rounded-lg">
                    <iframe
                      src={getGoogleMapsEmbedUrl() || ''}
                      width="100%"
                      height="100%"
                      style={{ border: 0 }}
                      allowFullScreen
                      loading="lazy"
                      referrerPolicy="no-referrer-when-downgrade"
                      className="absolute inset-0"
                      onLoad={() => setMapLoaded(true)}
                    />
                  </div>
                </div>
              )}

              <div className="space-y-2 text-sm">
                <div className="flex items-start gap-2">
                  <MapPin className="h-4 w-4 mt-0.5 flex-shrink-0 text-white" />
                  <span className="text-white">{venue.location.address || '住所情報が登録されていません'}</span>
                </div>
                {venue.venueWebsite && (
                  <a 
                    href={venue.venueWebsite}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-white hover:text-white/80"
                  >
                    <Globe className="h-4 w-4" />
                    <span>会場公式サイト</span>
                    <ExternalLink className="h-3 w-3" />
                  </a>
                )}
              </div>
        </div>
        
        {/* 参加予定ボタン（基本情報セクション右下に固定） */}
        <div className="absolute bottom-4 right-4 md:bottom-6 md:right-6">
          <AttendanceButton
            venueId={venueId}
            venueName={venue.name}
            isAttending={isAttending}
            onAttendanceChange={setIsAttending}
          />
        </div>
      </div>

      {/* ページ内ナビゲーション */}
      <nav
        className={`${
          isNavFixed ? 'fixed top-0 left-0 right-0 z-40 shadow-lg' : 'relative'
        } bg-white/95 dark:bg-gray-800/95 backdrop-blur-sm border-b border-gray-200 dark:border-gray-700 transition-all duration-300`}
      >
        <div className="max-w-6xl mx-auto px-3">
          <div className="flex flex-wrap items-center gap-1 py-1.5">
            {sections.map((section) => (
              <button
                key={section.id}
                onClick={() => scrollToSection(section.id)}
                className="px-1.5 py-0.5 text-[11px] rounded bg-gray-100 dark:bg-gray-700 hover:bg-orange-500 hover:text-white dark:hover:bg-orange-600 transition-colors flex items-center gap-0.5"
              >
                <Hash className="h-2.5 w-2.5" />
                {section.label}
              </button>
            ))}
          </div>
        </div>
      </nav>

      {/* メインコンテンツ */}
      <div className="max-w-6xl mx-auto px-4 md:px-6">
          <div className="space-y-6 py-6">
            {/* 旅行計画チェックリスト */}
            <VenueTravelChecklist venueId={venueId} />

            {/* 参加者情報 */}
            <div id="attendees" className="bg-white/90 dark:bg-gray-800/90 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 backdrop-blur-sm">
              <VenueAttendeesList 
                venueId={venueId}
              />
            </div>

          {/* AI生成情報に関する注意書き */}
          <div className="bg-yellow-50 dark:bg-yellow-900/20 border-l-4 border-yellow-400 dark:border-yellow-600 p-4 rounded-r-lg">
            <div className="flex items-start gap-3">
              <Info className="h-5 w-5 text-yellow-600 dark:text-yellow-400 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="text-sm text-yellow-800 dark:text-yellow-200 font-medium mb-1">
                  情報の正確性について
                </p>
                <p className="text-xs text-yellow-700 dark:text-yellow-300">
                  このページに掲載されている情報の一部はAIによって生成・まとめられたものであり、誤情報が含まれている可能性があります。情報量が多いため精査に時間がかかりますが、誤りを発見次第、逐次修正してまいります。重要な情報については、必ず公式サイト等で最新情報をご確認ください。
                </p>
              </div>
            </div>
          </div>

          {/* 遠征アクセス情報 */}
          {(venue.access || venue.longDistanceAccess) && (
            <div 
              id="access"
              className="rounded-lg shadow-lg border"
              style={{
                background: 'linear-gradient(to bottom, #0284c7 0%, #7dd3fc 100%)',
                borderColor: '#0284c7',
                backdropFilter: 'blur(4px)'
              }}
            >
              <div 
                className="p-4 border-b"
                style={{
                  borderColor: '#0284c7'
                }}
              >
                <h3 className="text-lg font-semibold flex items-center gap-2" style={{ color: '#ffffff' }}>
                  <Plane className="h-5 w-5" />
                  遠征組向けアクセス情報
                </h3>
                {venue.longDistanceAccess?.recommendations && (
                  <p className="text-sm mt-2 flex items-start gap-2" style={{ color: '#ffffff' }}>
                    <Info className="h-4 w-4 mt-0.5 flex-shrink-0" />
                    <span>{venue.longDistanceAccess.recommendations}</span>
                  </p>
                )}
              </div>
              <div className="p-6 space-y-6">
                {/* 会場周辺のアクセス情報 */}
                {venue.access && (
                  <div>
                    <h4 className="text-md font-semibold mb-3 flex items-center gap-2" style={{ color: '#ffffff' }}>
                      <Train className="h-4 w-4" />
                      会場周辺のアクセス
                    </h4>
                    <div className="bg-white p-4 rounded-lg border border-gray-200">
                      <p className="text-sm text-gray-700 dark:text-gray-300 leading-relaxed whitespace-pre-line">
                        {venue.access}
                      </p>
                    </div>
                  </div>
                )}

                {/* 空港からのアクセス */}
                {venue.longDistanceAccess.fromAirport && venue.longDistanceAccess.fromAirport.length > 0 && (
                  <div>
                    <h4 className="text-md font-semibold mb-3 flex items-center gap-2" style={{ color: '#ffffff' }}>
                      <Plane className="h-4 w-4" />
                      空港からのアクセス
                    </h4>
                    <div className="space-y-4">
                      {venue.longDistanceAccess.fromAirport.map((route: AccessRoute, index: number) => (
                        <div key={index} className="bg-white p-4 rounded-lg border border-gray-200">
                          <div className="flex items-start justify-between mb-2">
                            <div className="flex-1">
                              <h5 className="font-semibold text-gray-900 dark:text-white">{route.from}</h5>
                              <p className="text-sm text-gray-600 dark:text-gray-400">{route.method}</p>
                            </div>
                            <div className="text-right">
                              <p className="text-sm font-medium text-blue-600 dark:text-blue-400">{route.time}</p>
                              {route.cost && <p className="text-xs text-gray-500 dark:text-gray-400">{route.cost}</p>}
                            </div>
                          </div>
                          <p className="text-sm text-gray-700 dark:text-gray-300 mb-2">{route.description}</p>
                          {route.notes && (
                            <p className="text-xs text-orange-600 dark:text-orange-400 bg-orange-50 dark:bg-orange-900/20 p-2 rounded">
                              ⚠️ {route.notes}
                            </p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 新幹線からのアクセス */}
                {venue.longDistanceAccess.fromShinkansen && venue.longDistanceAccess.fromShinkansen.length > 0 && (
                  <div>
                    <h4 className="text-md font-semibold mb-3 flex items-center gap-2" style={{ color: '#ffffff' }}>
                      <Train className="h-4 w-4" />
                      新幹線でのアクセス
                    </h4>
                    <div className="space-y-4">
                      {venue.longDistanceAccess.fromShinkansen.map((route: AccessRoute, index: number) => (
                        <div key={index} className="bg-white p-4 rounded-lg border border-gray-200">
                          <div className="flex items-start justify-between mb-2">
                            <div className="flex-1">
                              <h5 className="font-semibold text-gray-900 dark:text-white">{route.from}</h5>
                              <p className="text-sm text-gray-600 dark:text-gray-400">{route.method}</p>
                            </div>
                            <div className="text-right">
                              <p className="text-sm font-medium text-green-600 dark:text-green-400">{route.time}</p>
                              {route.cost && <p className="text-xs text-gray-500 dark:text-gray-400">{route.cost}</p>}
                            </div>
                          </div>
                          <p className="text-sm text-gray-700 dark:text-gray-300 mb-2">{route.description}</p>
                          {route.notes && (
                            <p className="text-xs text-orange-600 dark:text-orange-400 bg-orange-50 dark:bg-orange-900/20 p-2 rounded">
                              ⚠️ {route.notes}
                            </p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 高速バスでのアクセス */}
                {venue.longDistanceAccess.fromExpressBus && venue.longDistanceAccess.fromExpressBus.length > 0 && (
                  <div>
                    <h4 className="text-md font-semibold mb-3 flex items-center gap-2" style={{ color: '#ffffff' }}>
                      <Bus className="h-4 w-4" />
                      高速バスでのアクセス
                    </h4>
                    <div className="space-y-4">
                      {venue.longDistanceAccess.fromExpressBus.map((route: AccessRoute, index: number) => (
                        <div key={index} className="bg-white p-4 rounded-lg border border-gray-200">
                          <div className="flex items-start justify-between mb-2">
                            <div className="flex-1">
                              <h5 className="font-semibold text-gray-900 dark:text-white">{route.from}</h5>
                              <p className="text-sm text-gray-600 dark:text-gray-400">{route.method}</p>
                            </div>
                            <div className="text-right">
                              <p className="text-sm font-medium text-purple-600 dark:text-purple-400">{route.time}</p>
                              {route.cost && <p className="text-xs text-gray-500 dark:text-gray-400">{route.cost}</p>}
                            </div>
                          </div>
                          <p className="text-sm text-gray-700 dark:text-gray-300 mb-2">{route.description}</p>
                          {route.notes && (
                            <p className="text-xs text-orange-600 dark:text-orange-400 bg-orange-50 dark:bg-orange-900/20 p-2 rounded">
                              ⚠️ {route.notes}
                            </p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 車でのアクセス */}
                {venue.longDistanceAccess.fromCar && venue.longDistanceAccess.fromCar.length > 0 && (
                  <div>
                    <h4 className="text-md font-semibold mb-3 flex items-center gap-2" style={{ color: '#ffffff' }}>
                      <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                      </svg>
                      車でのアクセス
                    </h4>
                    <div className="space-y-4">
                      {venue.longDistanceAccess.fromCar.map((route: AccessRoute, index: number) => (
                        <div key={index} className="bg-white p-4 rounded-lg border border-gray-200">
                          <div className="flex items-start justify-between mb-2">
                            <div className="flex-1">
                              <h5 className="font-semibold text-gray-900 dark:text-white">{route.from}</h5>
                              <p className="text-sm text-gray-600 dark:text-gray-400">{route.method}</p>
                            </div>
                            <div className="text-right">
                              <p className="text-sm font-medium text-orange-600 dark:text-orange-400">{route.time}</p>
                              {route.cost && <p className="text-xs text-gray-500 dark:text-gray-400">{route.cost}</p>}
                            </div>
                          </div>
                          <p className="text-sm text-gray-700 dark:text-gray-300 mb-2">{route.description}</p>
                          {route.notes && (
                            <p className="text-xs text-orange-600 dark:text-orange-400 bg-orange-50 dark:bg-orange-900/20 p-2 rounded">
                              ⚠️ {route.notes}
                            </p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* コインロッカー情報 */}
          <div id="lockers" className="bg-white/90 dark:bg-gray-800/90 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 backdrop-blur-sm">
            <div className="p-4 border-b border-gray-200 dark:border-gray-700">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                <Package className="h-5 w-5" />
                コインロッカー情報
              </h3>
            </div>
            <div className="p-6">
              {venue.coinLockers && venue.coinLockers.length > 0 ? (
                <ul className="space-y-3">
                  {[...venue.coinLockers].sort((a, b) => {
                    if (a.recommended && !b.recommended) return -1;
                    if (!a.recommended && b.recommended) return 1;
                    return 0;
                  }).map((locker, index) => (
                    <FacilityItem
                      key={index}
                      name={locker.location}
                      description={locker.description}
                      recommended={locker.recommended}
                      recommendComment={locker.recommendComment}
                      icon={<MapPin className="h-4 w-4 text-blue-600 dark:text-blue-400" />}
                    >
                      <div className="space-y-1 mt-1">
                        {locker.price && (
                          <p className="text-sm text-green-600 dark:text-green-400">料金: {locker.price}</p>
                        )}
                        {locker.distance && (
                          <p className="text-sm text-blue-600 dark:text-blue-400">距離: {locker.distance}</p>
                        )}
                      </div>
                      <div className="flex gap-2 mt-2">
                        {locker.website && (
                          <a 
                            href={locker.website}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                          >
                            <Globe className="h-3 w-3" />
                            詳細情報
                            <ExternalLink className="h-3 w-3" />
                          </a>
                        )}
                        {locker.mapsUrl && (
                          <a 
                            href={locker.mapsUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                          >
                            <MapPin className="h-3 w-3" />
                            地図
                            <ExternalLink className="h-3 w-3" />
                          </a>
                        )}
                      </div>
                    </FacilityItem>
                  ))}
                </ul>
              ) : (
                <p className="text-gray-500 dark:text-gray-400 text-sm">
                  コインロッカー情報は現在登録されていません
                </p>
              )}
            </div>
          </div>

          {/* 駐車場情報 */}
          <div 
            id="parking"
            className="rounded-lg shadow-lg border overflow-hidden"
            style={{
              background: 'linear-gradient(to bottom, #52525b 0%, #18181b 100%)',
              borderColor: '#3f3f46',
              backdropFilter: 'blur(4px)'
            }}
          >
            <div 
              className="p-4 border-b"
              style={{
                borderColor: '#3f3f46'
              }}
            >
              <h2 className="text-lg font-semibold flex items-center gap-2" style={{ color: '#ffffff' }}>
                <ParkingCircle className="h-5 w-5" />
                駐車場情報
              </h2>
            </div>
            <div className="p-6">
              {/* parkingInfo（公式サイトからの詳細情報）を最初に表示 */}
              {venue.parkingInfo && (
                <div className="mb-6 pb-6 border-b border-gray-600 dark:border-gray-600">
                  <h3 className="text-sm font-semibold mb-3 flex items-center gap-2" style={{ color: '#ffffff' }}>
                    <ParkingCircle className="h-4 w-4 text-purple-400" />
                    会場公式駐車場情報
                  </h3>
                  <p className="text-sm leading-relaxed whitespace-pre-line" style={{ color: '#e5e7eb' }}>
                    {venue.parkingInfo}
                  </p>
                </div>
              )}

              {/* parkingOptions（周辺駐車場リスト） */}
              {venue.parkingOptions && venue.parkingOptions.length > 0 ? (
                <div>
                  {venue.parkingInfo && (
                    <h3 className="text-sm font-semibold mb-4 flex items-center gap-2" style={{ color: '#ffffff' }}>
                      <ParkingCircle className="h-4 w-4" />
                      周辺の駐車場
                    </h3>
                  )}
                  <ul className="space-y-4">
                      {[...venue.parkingOptions].sort((a, b) => {
                        if (a.recommended && !b.recommended) return -1;
                        if (!a.recommended && b.recommended) return 1;
                        return 0;
                      }).map((parking, index) => (
                        <FacilityItem
                          key={index}
                          name={parking.name}
                          description={parking.description}
                          recommended={parking.recommended}
                          recommendComment={parking.recommendComment}
                          icon={<ParkingCircle className="h-5 w-5 text-blue-600 dark:text-blue-400" />}
                        >
                          <div className="flex flex-wrap gap-2 mb-2">
                            {parking.distance && (
                              <span className="inline-flex items-center gap-1 text-xs bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300 px-2 py-1 rounded">
                                <MapPin className="h-3 w-3" />
                                {parking.distance}
                              </span>
                            )}
                            {parking.price && (
                              <span className="inline-flex items-center text-xs bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300 px-2 py-1 rounded">
                                {parking.price}
                              </span>
                            )}
                          </div>
                          {parking.address && (
                            <p className="text-xs text-gray-500 dark:text-gray-400 mb-2">住所: {parking.address}</p>
                          )}
                          <div className="flex gap-2">
                            {parking.website && (
                              <a 
                                href={parking.website}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                              >
                                <Globe className="h-3 w-3" />
                                詳細・予約
                                <ExternalLink className="h-3 w-3" />
                              </a>
                            )}
                            {parking.mapsUrl && (
                              <a 
                                href={parking.mapsUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                              >
                                <MapPin className="h-3 w-3" />
                                地図
                                <ExternalLink className="h-3 w-3" />
                              </a>
                            )}
                          </div>
                        </FacilityItem>
                      ))}
                    </ul>
                  </div>
                ) : !venue.parkingInfo && (
                  <p className="text-gray-500 dark:text-gray-400 text-sm">
                    駐車場情報は現在登録されていません
                  </p>
                )}
            </div>
          </div>

          {/* 開場前の時間潰しスポット */}
          {venue.cafes && venue.cafes.length > 0 && (
            <div id="cafes" className="bg-white/90 dark:bg-gray-800/90 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 backdrop-blur-sm">
              <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                  <Coffee className="h-5 w-5" />
                  開場前の時間潰しスポット
                </h3>
              </div>
              <div className="p-6">
                <ul className="space-y-3">
                  {[...venue.cafes].sort((a, b) => {
                    if (a.recommended && !b.recommended) return -1;
                    if (!a.recommended && b.recommended) return 1;
                    return 0;
                  }).map((cafe, index) => (
                    <FacilityItem
                      key={index}
                      name={cafe.name}
                      description={cafe.description}
                      recommended={cafe.recommended}
                      recommendComment={cafe.recommendComment}
                      icon={<Coffee className="h-4 w-4 text-amber-600 dark:text-amber-400" />}
                    >
                      <div className="flex flex-wrap gap-2 mt-2">
                        {cafe.openTime && (
                          <span className="inline-flex items-center gap-1 text-xs bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300 px-2 py-1 rounded">
                            <Clock className="h-3 w-3" />
                            {cafe.openTime}
                          </span>
                        )}
                        {cafe.distance && (
                          <span className="inline-flex items-center gap-1 text-xs bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300 px-2 py-1 rounded">
                            <MapPin className="h-3 w-3" />
                            {cafe.distance}
                          </span>
                        )}
                        {cafe.wifi && (
                          <span className="inline-flex items-center gap-1 text-xs bg-purple-100 text-purple-700 dark:bg-purple-900 dark:text-purple-300 px-2 py-1 rounded">
                            <Wifi className="h-3 w-3" />
                            Wi-Fi
                          </span>
                        )}
                      </div>
                      <div className="flex gap-2 mt-2">
                        {cafe.website && (
                          <a 
                            href={cafe.website}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                          >
                            <Globe className="h-3 w-3" />
                            公式サイト
                            <ExternalLink className="h-3 w-3" />
                          </a>
                        )}
                        {cafe.mapsUrl && (
                          <a 
                            href={cafe.mapsUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                          >
                            <MapPin className="h-3 w-3" />
                            地図
                            <ExternalLink className="h-3 w-3" />
                          </a>
                        )}
                      </div>
                    </FacilityItem>
                  ))}
                </ul>
              </div>
            </div>
          )}

          {/* 近隣情報 */}
          <div className="space-y-6">

            {/* グルメ情報 */}
            <div
              id="restaurants"
              className="rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 backdrop-blur-sm bg-[linear-gradient(to_bottom,#fdba74_0%,#fb923c_100%)] md:bg-white"
              style={{
                borderColor: '#fb923c',
                backdropFilter: 'blur(4px)'
              }}
            >
              <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                  <Coffee className="h-5 w-5" />
                  近隣のグルメ
                </h3>
              </div>
              <div className="p-6">
                {venue.nearbyRestaurants && venue.nearbyRestaurants.length > 0 ? (
                  <ul className="space-y-3">
                    {[...venue.nearbyRestaurants].sort((a, b) => {
                      if (a.recommended && !b.recommended) return -1;
                      if (!a.recommended && b.recommended) return 1;
                      return 0;
                    }).map((restaurant, index) => (
                      <FacilityItem
                        key={index}
                        name={restaurant.name}
                        description={restaurant.description}
                        recommended={restaurant.recommended}
                        recommendComment={restaurant.recommendComment}
                        icon={<Coffee className="h-4 w-4 text-orange-500" />}
                      >
                        <div className="flex flex-wrap gap-2 mt-2">
                          <span className="inline-flex items-center text-xs bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-300 px-2 py-1 rounded">
                            {restaurant.cuisine}
                          </span>
                          {restaurant.distance && (
                            <span className="inline-flex items-center gap-1 text-xs bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300 px-2 py-1 rounded">
                              <MapPin className="h-3 w-3" />
                              {restaurant.distance}
                            </span>
                          )}
                          {restaurant.openTime && (
                            <span className="inline-flex items-center gap-1 text-xs bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300 px-2 py-1 rounded">
                              <Clock className="h-3 w-3" />
                              {restaurant.openTime}
                            </span>
                          )}
                          {restaurant.price && (
                            <span className="inline-flex items-center text-xs bg-purple-100 text-purple-700 dark:bg-purple-900 dark:text-purple-300 px-2 py-1 rounded">
                              {restaurant.price}
                            </span>
                          )}
                        </div>
                        <div className="flex gap-2 mt-2">
                          {restaurant.website && (
                            <a 
                              href={restaurant.website}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                            >
                              <Globe className="h-3 w-3" />
                              公式サイト
                              <ExternalLink className="h-3 w-3" />
                            </a>
                          )}
                          {restaurant.mapsUrl && (
                            <a 
                              href={restaurant.mapsUrl}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                            >
                              <MapPin className="h-3 w-3" />
                              地図
                              <ExternalLink className="h-3 w-3" />
                            </a>
                          )}
                        </div>
                      </FacilityItem>
                    ))}
                  </ul>
                ) : (
                  <p className="text-gray-500 dark:text-gray-400 text-sm">
                    グルメ情報が登録されていません
                  </p>
                )}
              </div>
            </div>

            {/* 観光スポット */}
            <div id="spots" className="bg-white/90 dark:bg-gray-800/90 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 backdrop-blur-sm">
              <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                  <Camera className="h-5 w-5" />
                  近隣の観光スポット
                </h3>
              </div>
              <div className="p-6">
                {venue.nearbyAttractions && venue.nearbyAttractions.length > 0 ? (
                  <ul className="space-y-3">
                    {venue.nearbyAttractions.map((attraction: NearbyAttraction, index: number) => (
                      <li key={index} className="border-b border-gray-200 dark:border-gray-600 last:border-b-0 pb-3 last:pb-0">
                        <div className="flex items-start gap-2">
                          <Star className="h-4 w-4 text-yellow-500 mt-1 flex-shrink-0" />
                          <div className="flex-1">
                            <h4 className="font-medium text-gray-900 dark:text-white">
                              {attraction.name}
                            </h4>
                            <p className="text-sm text-gray-600 dark:text-gray-300 mt-1">
                              {attraction.description}
                            </p>
                            {attraction.distance && (
                              <p className="text-sm text-blue-600 dark:text-blue-400 mt-1">
                                会場から {attraction.distance}
                              </p>
                            )}
                            {attraction.website && (
                              <a 
                                href={attraction.website}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300 mt-2"
                              >
                                <Globe className="h-3 w-3" />
                                詳細情報
                                <ExternalLink className="h-3 w-3" />
                              </a>
                            )}
                          </div>
                        </div>
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p className="text-gray-500 dark:text-gray-400 text-sm">
                    観光情報が登録されていません
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* 聖地情報 */}
          {venue.holyPlaces && venue.holyPlaces.length > 0 && (
            <div id="holy" className="bg-white/90 dark:bg-gray-800/90 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 backdrop-blur-sm">
              <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                  <Star className="h-5 w-5" />
                  れをる聖地
                </h3>
              </div>
              <div className="p-6">
                <ul className="space-y-3">
                  {venue.holyPlaces.map((holyPlace: HolyPlace, index: number) => (
                    <li key={index} className="border-b border-gray-200 dark:border-gray-600 last:border-b-0 pb-3 last:pb-0">
                      <div className="flex items-start gap-2">
                        <Star className="h-4 w-4 text-yellow-500 mt-1 flex-shrink-0" />
                        <div className="flex-1">
                          <h4 className="font-medium text-gray-900 dark:text-white">
                            {holyPlace.name}
                          </h4>
                          <p className="text-sm text-gray-600 dark:text-gray-300 mt-1">
                            {holyPlace.description}
                          </p>
                          {holyPlace.distance && (
                            <p className="text-sm text-blue-600 dark:text-blue-400 mt-1">
                              会場から {holyPlace.distance}
                            </p>
                          )}
                          {holyPlace.website && (
                            <a 
                              href={holyPlace.website}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300 mt-2"
                            >
                              <Globe className="h-3 w-3" />
                              詳細情報
                              <ExternalLink className="h-3 w-3" />
                            </a>
                          )}
                        </div>
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          )}

          {/* 宿泊施設情報 */}
          {venue.accommodations && venue.accommodations.length > 0 && (
            <div 
              id="hotels"
              className="rounded-lg shadow-lg border"
              style={{
                background: 'linear-gradient(to bottom, #1e3a5f 0%, #0a0e1a 100%)',
                borderColor: '#334155',
                backdropFilter: 'blur(4px)'
              }}
            >
              <div 
                className="p-4 border-b"
                style={{
                  borderColor: '#2d3748'
                }}
              >
                <h3 className="text-lg font-semibold flex items-center gap-2" style={{ color: '#fbbf24' }}>
                  <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
                  </svg>
                  会場近くの宿泊施設
                </h3>
              </div>
              <div className="p-6">
                <div className="grid gap-4 md:grid-cols-2">
                  {[...venue.accommodations].sort((a, b) => {
                    if (a.recommended && !b.recommended) return -1
                    if (!a.recommended && b.recommended) return 1
                    return 0
                  }).map((accommodation, index) => (
                    <div key={index} className="bg-white/80 dark:bg-gray-900/80 rounded-lg p-4 shadow border border-gray-200 dark:border-gray-700 flex flex-col gap-2">
                      <div className="flex items-center gap-2">
                        <span className="font-semibold text-gray-900 dark:text-white">{accommodation.name}</span>
                        {accommodation.recommended && (
                          <span className="inline-flex items-center text-xs bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-300 px-2 py-1 rounded">おすすめ</span>
                        )}
                      </div>
                      <div className="text-sm text-gray-700 dark:text-gray-300">{accommodation.description}</div>
                      <div className="flex gap-2 text-sm">
                        {accommodation.website && (
                          <a 
                            href={accommodation.website}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1 text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                          >
                            <Globe className="h-3 w-3" />
                            公式サイト
                            <ExternalLink className="h-3 w-3" />
                          </a>
                        )}
                        {accommodation.mapsUrl && (
                          <a 
                            href={accommodation.mapsUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1 text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                          >
                            <MapPin className="h-3 w-3" />
                            地図
                            <ExternalLink className="h-3 w-3" />
                          </a>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* 他の開催予定会場（前1公演、後2公演） */}
          <div className="bg-white/90 dark:bg-gray-800/90 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 p-6 backdrop-blur-sm">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">他の開催予定会場</h3>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {(() => {
                const currentIndex = VENUES_2026.findIndex(v => v.id === venueId)
                const prevVenue = currentIndex > 0 ? [VENUES_2026[currentIndex - 1]] : []
                const nextVenues = VENUES_2026.slice(currentIndex + 1, currentIndex + 3)
                const displayVenues = [...prevVenue, ...nextVenues]
                
                return displayVenues.map(otherVenue => (
                  <Link
                    key={otherVenue.id}
                    to={`/bijigaku-navi/venue/${otherVenue.id}/`}
                    className="flex items-center justify-between p-3 bg-gray-50 hover:bg-gray-100 dark:bg-gray-700 dark:hover:bg-gray-600 rounded-lg transition-colors group"
                  >
                    <div className="flex-1">
                      <div className="text-sm font-medium text-gray-900 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400">
                        {otherVenue.location.prefecture}
                      </div>
                      <div className="text-xs text-gray-600 dark:text-gray-300">
                        {new Date(otherVenue.date).toLocaleDateString('ja-JP', { 
                          month: 'numeric', 
                          day: 'numeric',
                          weekday: 'short'
                        })}
                      </div>
                    </div>
                    <ArrowLeft className="h-4 w-4 text-gray-400 rotate-180 group-hover:text-blue-600 dark:group-hover:text-blue-400" />
                  </Link>
                ))
              })()}
            </div>
            <div className="mt-4 text-center">
              <Link
                to="/bijigaku-navi/"
                className="inline-flex items-center gap-2 text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300 font-medium"
              >
                すべての会場を見る
                <ArrowLeft className="h-4 w-4 rotate-180" />
              </Link>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

export default VenueDetail;